import streamlit as st

st.title("Chai Taste Poll")

col1, col2 = st.columns(2)

with col1:
    st.header("Masala Chai")
    st.image("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRgtMlr1NzfiDu7n8VSlm4dG9KePAFbc-U14A&s", width=200)
    vote1 = st.button("Vote Masala Chai")
    
with col2:
    st.header("Adarak Chai")
    st.image("data:image/jpeg;base64,", width=200)
    vote2 = st.button("Vote Adarak Chai")
    
if vote1:
    st.success("Thanks for voting masala chai")
elif vote2:
    st.success("Thanks for voting Adarak chai")
    
name = st.sidebar.text_input("Enter your name")
tea = st.sidebar.selectbox("choose your chai", ["Masala", "Kesar", "Adarak"])

st.write(f"welcome {name} and your chai is getting ready")

with st.expander("Show chai making Instruction"):
    st.write("""
             1. Boil water with tea leaves
             2. if want add sugar accordingly (optional)
             3. add milk (optional)
             4. serve hot
             """)